// <diletta-status-tag> — a INSTÂNCIA WEB de `design-system-status-tag`.
//
// 67 usos no BackOffice. Ela só pôde ser escrita em 07/09/2026, quando o Dart
// dela passou a pintar por PAPEL nos sete tons — antes pintava por degrau, e o
// tom `secure` era o único cuja cor não coincidia com papel nenhum.
import { papeisDe, estiloDa, eixo } from './base.js';

const SLUG = 'design-system-status-tag';
const TONE = ['warning', 'neutral', 'primary', 'success', 'danger', 'secure', 'pending'];
// `compacta` corta em uma linha; `ampla` deixa quebrar. O eixo nasceu da pílula de
// erro do chat, onde o texto é uma frase e não um estado de duas palavras.
const PORTE = ['compacta', 'ampla'];

// `pending` traz o relógio por default, e os outros seis NÃO têm glifo: neles a
// cor do tom já carrega o significado. É a regra da spec, e ela é do DS — não uma
// escolha de quem chama.
const RELOGIO =
  '<svg viewBox="0 0 16 16" aria-hidden="true" focusable="false">' +
  '<circle cx="8" cy="8" r="5.5" fill="none" stroke="currentColor" stroke-width="1.4"/>' +
  '<path d="M8 5v3.2l2 1.2" fill="none" stroke="currentColor" stroke-width="1.4" ' +
  'stroke-linecap="round"/></svg>';

class DilettaStatusTag extends HTMLElement {
  static observedAttributes = ['tone', 'porte', 'label', 'icone'];

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() { this.render(); }
  attributeChangedCallback() { if (this.shadowRoot) this.render(); }

  render() {
    const tone = eixo(this, 'tone', TONE, 'neutral');
    const ampla = eixo(this, 'porte', PORTE, 'compacta') === 'ampla';
    const p = papeisDe(SLUG, { Tone: tone });
    const label = this.getAttribute('label') || '';
    // O glifo é do TOM: `pending` traz relógio sem ninguém pedir, e os outros só o
    // trazem se quem chama mandar. Cor sozinha carregaria o estado nos outros seis.
    const glifo = tone === 'pending' ? RELOGIO : (this.hasAttribute('icone') ? '<slot name="icone"></slot>' : '');

    this.shadowRoot.innerHTML = `
      <style>
        :host { display: inline-flex; }
        .tag {
          box-sizing: border-box;
          ${ampla ? 'min-height: 20px;' : 'height: 20px;'} padding: 0 8px;
          display: inline-flex; align-items: ${ampla ? 'flex-start' : 'center'}; gap: 4px;
          border-width: 1px; border-style: solid; border-radius: 999px;
          font-size: var(--cps-type-caption-size, 11px);
          /* Compacta corta em uma linha; ampla deixa quebrar. Sem o porte, uma
             frase inteira numa tag vira reticência no primeiro corte.
             (Sem crase: template literal.) */
          line-height: ${ampla ? '1.4' : '1'};
          ${ampla ? 'white-space: normal;' : 'white-space: nowrap;'}
          ${estiloDa(p)}
        }
        .tag svg, .tag ::slotted(svg) { width: 12px; height: 12px; flex: none;
          ${ampla ? 'margin-top: 3px;' : ''} }
        .rotulo { ${ampla ? '' : 'overflow: hidden; text-overflow: ellipsis;'} }
      </style>
      <span class="tag" part="tag">${glifo}<span class="rotulo">${label}</span></span>`;
  }
}

customElements.define('diletta-status-tag', DilettaStatusTag);
export { DilettaStatusTag };
